import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI } from "@google/genai";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const PORT = 3000;

app.use(express.json({ limit: "50mb" }));
app.use(express.urlencoded({ extended: true, limit: "50mb" }));

// Initialize Gemini Client
const getGeminiClient = () => {
  if (!process.env.GEMINI_API_KEY) {
    return null;
  }
  return new GoogleGenAI({
    apiKey: process.env.GEMINI_API_KEY,
    httpOptions: {
      headers: {
        "User-Agent": "aistudio-build",
      },
    },
  });
};

// 1. Health check
app.get("/api/health", (req, res) => {
  res.json({ status: "ok", mode: "8-bit-retro-reader" });
});

// 2. Direct URL Proxy Fetcher (bypasses CORS restrictions)
app.post("/api/proxy-fetch", async (req, res) => {
  try {
    const { url } = req.body;
    if (!url || typeof url !== "string") {
      return res.status(400).json({ error: "Missing or invalid url parameter." });
    }

    // Validate URL
    let parsedUrl: URL;
    try {
      parsedUrl = new URL(url);
    } catch {
      return res.status(400).json({ error: "Invalid URL format." });
    }

    const response = await fetch(parsedUrl.toString(), {
      headers: {
        "User-Agent": "RetroReader/1.0 (8-Bit Comic & Book Engine)",
        Accept: "*/*",
      },
    });

    if (!response.ok) {
      return res.status(response.status).json({
        error: `Failed to fetch remote file: HTTP ${response.status} ${response.statusText}`,
      });
    }

    const contentType = response.headers.get("content-type") || "application/octet-stream";
    const arrayBuffer = await response.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Try to guess filename from URL or header
    let filename = path.basename(parsedUrl.pathname) || "downloaded_file";
    const contentDisposition = response.headers.get("content-disposition");
    if (contentDisposition && contentDisposition.includes("filename=")) {
      const match = contentDisposition.match(/filename=["']?([^"';]+)["']?/);
      if (match && match[1]) {
        filename = match[1];
      }
    }

    res.setHeader("Content-Type", contentType);
    res.setHeader("Content-Disposition", `inline; filename="${encodeURIComponent(filename)}"`);
    res.setHeader("Content-Length", buffer.length.toString());
    res.send(buffer);
  } catch (error: any) {
    console.error("Proxy fetch error:", error);
    res.status(500).json({ error: error.message || "Failed to proxy fetch file." });
  }
});

// 3. Gemini AI: Oracle / Sage Reader Assistant
app.post("/api/ai/oracle", async (req, res) => {
  try {
    const ai = getGeminiClient();
    if (!ai) {
      return res.status(500).json({
        error: "GEMINI_API_KEY is not configured in server environment.",
      });
    }

    const { prompt, pageContext, bookTitle, currentFormat, imageBase64, mode } = req.body;

    let systemInstruction = `You are "SAGE 8-BIT" (El Oráculo Pixel), a witty, knowledgeable, retro 8-bit RPG master and literary wizard living inside a vintage handheld gaming cartridge.
Your duty is to assist the player/reader with reading comprehension, lore explanation, comic & manga panel translation, chapter summaries, and answering inquiries.
Maintain a fun, classic 8-bit gamer tone (using retro RPG metaphors like "EXP", "Level Up", "Lore Scroll", "Quest Briefing", "Mana"), but provide genuinely insightful, accurate, and helpful answers. Respond in Spanish (or the language the user speaks/requests). Keep formatting clean and readable.`;

    if (mode === "translate") {
      systemInstruction += ` Focus on translating the text or dialogue clearly and explaining cultural nuances or puns if from manga/comic panels.`;
    } else if (mode === "summary") {
      systemInstruction += ` Provide a concise, thrilling "Quest Log Summary" of the given page or section with key events and takeaways.`;
    }

    const contents: any[] = [];

    if (imageBase64) {
      // Clean base64 string
      const match = imageBase64.match(/^data:([^;]+);base64,(.+)$/);
      const mimeType = match ? match[1] : "image/jpeg";
      const rawBase64 = match ? match[2] : imageBase64;

      contents.push({
        inlineData: {
          mimeType,
          data: rawBase64,
        },
      });
    }

    let userPromptText = `[LIBRO/CÓMIC]: ${bookTitle || "Cartucho Desconocido"} (${currentFormat || "Doc"})\n`;
    if (pageContext) {
      userPromptText += `[CONTENIDO DE LA PÁGINA ACTUAL]:\n${pageContext.substring(0, 4000)}\n\n`;
    }
    userPromptText += `[CONSULTA DEL JUGADOR]: ${prompt || "Analiza esta página y dame un resumen o datos curiosos"}`;

    contents.push({
      text: userPromptText,
    });

    const response = await ai.models.generateContent({
      model: "gemini-3.7-flash",
      contents: { parts: contents },
      config: {
        systemInstruction,
        temperature: 0.7,
      },
    });

    res.json({ text: response.text });
  } catch (error: any) {
    console.error("AI Oracle Error:", error);
    res.status(500).json({ error: error.message || "Error al invocar al Oráculo IA." });
  }
});

// Vite & Static serving configuration
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`🎮 [8-BIT RETRO READER] Server listening on http://0.0.0.0:${PORT}`);
  });
}

startServer();
